WITH ranked AS (SELECT * FROM store_sales QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY sale_date NULLS LAST, id) = 1) SELECT CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, store_id, STDDEV_SAMP(revenue) AS revenue_stddev, BIT_AND(units) AS units_bit_and, PERCENTILE_APPROX(revenue, 0.5) AS revenue_p50, MIN(revenue) AS min_revenue, BIT_AND(units) AS units_bit_and_2, GROUPING(CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM ranked GROUP BY GROUPING SETS ((CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id), (CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) ORDER BY units_bit_and_2 DESC
